hero-statue.source:
const S = params.height / 2.8;
const marble = { preset: 'stone', roughness: 0.35, metalness: 0.0, color: '#ffffff' };
const stoneM = { preset: 'stone', roughness: 0.9, flatShading: true, color: '#ffffff' };
const darkM = { preset: 'stone', color: '#2b2a29', roughness: 0.8 };
const lineM = { preset: 'stone', color: '#c9c3b4', roughness: 0.7 };
const vein = (m) => m.vertexColor((x, y, z) => {
  const n = Math.abs(api.noise3(x * 3.2, y * 2.4, z * 3.2));
  const n2 = Math.abs(api.noise3(x * 7 + 5, y * 5, z * 7));
  let t = 0;
  if (n < 0.09) t = params.veining; else if (n2 < 0.05) t = params.veining * 0.6;
  return api.mix(params.marbleColor, '#8a8c92', t);
});
const stoneCol = (m) => m.vertexColor((x, y, z) => api.mix(params.stoneColor, '#4d4b48', 0.4 * (0.5 + 0.5 * api.noise3(x * 4, y * 4, z * 4))));
const add = (m, isStone) => { m.scale(S); if (isStone) { stoneCol(m); api.add(m, stoneM); } else { vein(m); api.add(m, marble); } };
add(api.box(0.9, 0.2, 0.9).translate(0, 0.1, 0), true);
add(api.box(0.75, 0.15, 0.75).translate(0, 0.275, 0), true);
add(api.box(0.6, 0.5, 0.6).translate(0, 0.6, 0), true);
add(api.box(0.72, 0.1, 0.72).translate(0, 0.9, 0), true);
for (let s = 0; s < 4; s++) {
  const plate = api.box(0.4, 0.12, 0.014).translate(0, 0.6, 0.303).rotate(0, s * 90, 0).scale(S);
  api.add(plate, darkM);
  for (let l = 0; l < 3; l++) {
    const w = [0.32, 0.28, 0.22][l];
    api.add(api.box(w, 0.012, 0.012).translate(0, 0.635 - l * 0.035, 0.312).rotate(0, s * 90, 0).scale(S), lineM);
  }
}
const y0 = 0.95;
const P = [[0, 0], [0.30, 0], [0.31, 0.04], [0.27, 0.08], [0.285, 0.12], [0.255, 0.16], [0.27, 0.2], [0.24, 0.26], [0.255, 0.3], [0.225, 0.4], [0.24, 0.44], [0.21, 0.55], [0.225, 0.59], [0.195, 0.7], [0.21, 0.74], [0.185, 0.85], [0.2, 0.89], [0.19, 1.0], [0.21, 1.04], [0.2, 1.15], [0.23, 1.25], [0.23, 1.33], [0.17, 1.42], [0.07, 1.47], [0.05, 1.5], [0, 1.5]];
const robe = api.lathe(P.map(p => [p[0], p[1] + y0]), 28);
robe.displace((x, y, z) => 0.012 * Math.sin(Math.atan2(z, x) * 7 + y * 3));
add(robe, false);
add(api.sphere(0.2, 2).scale(1.25, 0.55, 0.8).translate(0, y0 + 1.33, 0), false);
// drape rings hugging the robe
for (let i = 0; i < 4; i++) {
  const yy = 0.18 + i * 0.22;
  const r = 0.27 - i * 0.022;
  add(api.torus(r, 0.03).rotate(90, 0, 0).scale(1, 1, 0.85).rotate(0, 0, (i % 2 ? 6 : -6)).translate(0, y0 + yy, 0), false);
}
// diagonal sash
add(api.tube([[-0.2, y0 + 1.3, 0.05], [-0.08, y0 + 1.1, 0.19], [0.05, y0 + 0.85, 0.2], [0.17, y0 + 0.6, 0.19]], 0.05, 10), false);
add(api.tube([[0.17, y0 + 0.6, 0.19], [0.2, y0 + 0.4, 0.2], [0.18, y0 + 0.2, 0.25]], 0.045, 8), false);
// feet
for (const sx of [-1, 1]) add(api.sphere(0.07, 2).scale(0.9, 0.5, 1.9).translate(sx * 0.1, y0 + 0.035, 0.29), false);
// left arm
add(api.sphere(0.07, 2).translate(-0.22, y0 + 1.3, 0), false);
add(api.tube([[-0.22, y0 + 1.3, 0], [-0.28, y0 + 1.1, 0.03], [-0.27, y0 + 0.88, 0.06]], 0.055, 10), false);
add(api.sphere(0.045, 2).translate(-0.27, y0 + 0.82, 0.07), false);
// right arm bent
add(api.sphere(0.07, 2).translate(0.22, y0 + 1.3, 0), false);
add(api.tube([[0.22, y0 + 1.3, 0], [0.31, y0 + 1.15, 0.06], [0.36, y0 + 1.1, 0.12]], 0.055, 10), false);
add(api.sphere(0.055, 2).translate(0.36, y0 + 1.1, 0.12), false);
add(api.tube([[0.36, y0 + 1.1, 0.12], [0.4, y0 + 1.35, 0.12], [0.4, y0 + 1.6, 0.1]], 0.05, 10), false);
add(api.sphere(0.05, 2).translate(0.4, y0 + 1.63, 0.1), false);
// wreath
const wc = [0.4, y0 + 1.76, 0.1];
const wr = api.torus(0.11, 0.018).rotate(0, 20, 0).translate(wc[0], wc[1], wc[2]);
wr.scale(S); wr.vertexColor(() => params.wreathColor); api.add(wr, marble);
for (let i = 0; i < 16; i++) {
  const a = i / 16 * Math.PI * 2;
  const lf = api.sphere(0.025, 1).scale(1, 0.5, 2).rotate(0, 0, a * 57.3 + 90).translate(Math.cos(a) * 0.11, Math.sin(a) * 0.11, 0).rotate(0, 20, 0).translate(wc[0], wc[1], wc[2]);
  lf.scale(S); lf.vertexColor(() => params.wreathColor); api.add(lf, marble);
}
// neck and head
add(api.cylinder(0.045, 0.055, 0.1, 10).translate(0, y0 + 1.52, 0), false);
const hc = y0 + 1.66;
const head = api.sphere(0.1, 3).scale(0.9, 1.1, 1).rotate(0, 0, params.tilt).translate(0, hc, 0);
add(head, false);
for (let i = 0; i < 30; i++) {
  const a = i * 2.4, k = i / 30;
  const el = 0.2 + k * 1.2;
  const hx = Math.cos(a) * Math.cos(el) * 0.1, hy = Math.sin(el) * 0.11, hz = Math.sin(a) * Math.cos(el) * 0.1;
  if (hz > 0.05 && hy < 0.07) continue;
  add(api.sphere(0.03, 1).translate(hx, hy, hz).rotate(0, 0, params.tilt).translate(0, hc, 0), false);
}
api.collider({ kind: 'box', halfExtents: [0.45 * S, 0.475 * S, 0.45 * S], offset: [0, 0.475 * S, 0] });
api.collider({ kind: 'cylinder', radius: 0.28 * S, halfHeight: 0.75 * S, offset: [0, 1.7 * S, 0] });
api.collider({ kind: 'box', halfExtents: [0.15 * S, 0.4 * S, 0.12 * S], offset: [0.35 * S, 2.45 * S, 0.1 * S] });
return api.build();

marble-cliff-stair.source:
const W=params.width,H=params.height,D=params.depth,N=Math.max(2,Math.round(params.tiers));
const fw=params.flightWidth,tg=params.tongue,tw=params.tongueWidth;
const h=H/N,SL=1.4,hw=W/2;
const zF=D/2,zB=-(D/2+tg);
const s=(D-4)/(N-1);
const marble={finish:'marble',color:params.color,roughness:0.5,surface:{layers:[{kind:'veins',amount:0.2},{kind:'grime',amount:0.45},{kind:'edgeWear',amount:0.6},{kind:'lichen',amount:0.15}]}};
const wallM={finish:'stone',color:params.wallColor,roughness:0.85,surface:{layers:[{kind:'tone',amount:0.45},{kind:'streaks',amount:0.6},{kind:'grime',amount:0.5},{kind:'moss',amount:0.35,mask:{noise:0.5}},{kind:'edgeWear',amount:0.4}]}};
const trimM={finish:'marble',color:params.trimColor,roughness:0.45,surface:{layers:[{kind:'grime',amount:0.4},{kind:'edgeWear',amount:0.6}]}};
const paveM={finish:'stone',color:'#d8cfbd',roughness:0.8,surface:{layers:[{kind:'tone',amount:0.5},{kind:'cracks',amount:0.3},{kind:'grime',amount:0.4}]}};
const nicheM={color:params.nicheColor,roughness:0.95};
const acc={wall:null,trim:null,niche:null,step:null,pave:null};
function put(key,m){ if(acc[key]===null){acc[key]=m;} else {acc[key].merge(m);} }
function zi(i){ return i===0 ? zF : zF - i*s; }
function parapet(xa,xb,y,zc){ if(xb-xa<0.2) return; const L=xb-xa,cx=(xa+xb)/2; put('trim',api.box(L,0.9,0.3).translate(cx,y+0.45,zc)); put('trim',api.box(L+0.05,0.1,0.42).translate(cx,y+0.95,zc)); api.collider({kind:'box',halfExtents:[L/2,0.5,0.15],offset:[cx,y+0.5,zc]}); }
const xb=hw-3.4, xa=-(hw-2.6);
function gap(i){ if(i===0) return [-tw/2,tw/2]; const d=(i%2===1)?1:-1; return d>0?[xb,hw]:[-hw,-xb]; }
const nb=Math.max(2,Math.round(W/3.6)), sp=W/nb;
for(let i=0;i<N;i++){
  const y0=i*h,y1=(i+1)*h,z=zi(i),face=z-0.35;
  put('wall',api.box(W,h,face-zB).translate(0,y0+h/2,(face+zB)/2));
  api.collider({kind:'box',halfExtents:[hw,h/2,(face-zB)/2],offset:[0,y0+h/2,(face+zB)/2]});
  for(let k=0;k<=nb;k++){ const x=-hw+k*sp; put('trim',api.box(0.7,h-0.55,0.4).translate(x,y0+(h-0.55)/2,z-0.2)); }
  for(let k=0;k<nb;k++){ const x=-hw+(k+0.5)*sp, nw=sp-1.5, nh=h*0.5, yb=y0+1.0;
    put('niche',api.box(nw,nh,0.06).translate(x,yb+nh/2,face+0.03));
    put('niche',api.cylinder(nw/2,nw/2,0.06,16).rotate(90,0,0).translate(x,yb+nh,face+0.03));
    put('trim',api.box(nw+0.3,0.18,0.3).translate(x,yb-0.09,face+0.15)); }
  put('trim',api.box(W+0.4,0.45,0.8).translate(0,y1-0.225,z-0.35));
  const back = (i+1<N) ? zi(i+1)-0.35 : zB;
  const len = (z-0.35)-back;
  put('pave',api.box(W-0.1,0.1,len).translate(0,y1-0.03,(z-0.35+back)/2));
  const g=gap(i);
  parapet(-hw,g[0],y1,z-0.5); parapet(g[1],hw,y1,z-0.5);
  if(i+1<N){ const zf=z-0.65, zb2=zi(i+1)-0.35, L=zf-zb2;
    for(const sx of [-1,1]){ put('trim',api.box(0.3,0.9,L).translate(sx*(hw-0.15),y1+0.45,(zf+zb2)/2)); api.collider({kind:'box',halfExtents:[0.15,0.5,L/2],offset:[sx*(hw-0.15),y1+0.5,(zf+zb2)/2]}); } }
}
if(tg>0){ put('wall',api.box(tw,h,tg).translate(0,h/2,zF+tg/2)); put('pave',api.box(tw,0.1,tg).translate(0,h-0.03,zF+tg/2)); api.collider({kind:'box',halfExtents:[tw/2,h/2,tg/2],offset:[0,h/2,zF+tg/2]}); }
for(let i=1;i<N;i++){
  const d=(i%2===1)?1:-1, y0=i*h, zc=zi(i)+fw/2, run=xb-xa;
  const n=Math.max(4,Math.round(h/0.172)), tr=run/n, rise=h/n, c=SL*run/h;
  for(let k=0;k<n;k++){ const xm=xa+(k+0.5)*tr; put('step',api.box(tr+0.01,rise+0.3,fw).translate(d*xm,y0+k*rise-0.3+(rise+0.3)/2,zc)); }
  let slab=[[xa,y0],[xa+c,y0],[xb,y0+h-SL],[xb,y0+h]];
  let rail=[[xa,y0],[xb,y0+h],[xb,y0+h+1],[xa,y0+1]];
  if(d<0){ slab=slab.map(p=>[-p[0],p[1]]).reverse(); rail=rail.map(p=>[-p[0],p[1]]).reverse(); }
  put('step',api.extrude(slab,fw).translate(0,0,zc));
  const zr=zc+fw/2-0.15;
  put('trim',api.extrude(rail,0.3).translate(0,0,zr));
  const hp=[]; for(const zz of [zc-fw/2,zc+fw/2]){ hp.push(d*xa,y0+rise*0.5,zz, d*xb,y0+h+rise*0.5,zz, d*xb,y0+h-SL,zz, d*(xa+c),y0,zz); }
  api.collider({kind:'hull',points:hp,offset:[0,0,0]});
  const rp=[]; for(const zz of [zr-0.15,zr+0.15]){ rp.push(d*xa,y0,zz, d*xb,y0+h,zz, d*xb,y0+h+1,zz, d*xa,y0+1,zz); }
  api.collider({kind:'hull',points:rp,offset:[0,0,0]});
  for(let px=xa+c+2.5; px<xb-0.6; px+=4){ const yu=y0+(px-(xa+c))*(h-SL)/(xb-xa-c); const ph=yu-y0; if(ph<0.9) continue;
    put('trim',api.box(0.7,ph+0.3,fw-0.6).translate(d*px,y0+(ph+0.3)/2,zc));
    put('trim',api.box(0.95,0.25,fw-0.35).translate(d*px,y0+0.125,zc));
    api.collider({kind:'box',halfExtents:[0.35,(ph+0.3)/2,(fw-0.6)/2],offset:[d*px,y0+(ph+0.3)/2,zc]}); }
  const lx=d*(xb+hw)/2, lw=hw-xb, lz=zi(i)+(fw-0.35)/2;
  put('step',api.box(lw,SL,fw+0.35).translate(lx,y0+h-SL/2,lz));
  api.collider({kind:'box',halfExtents:[lw/2,SL/2,(fw+0.35)/2],offset:[lx,y0+h-SL/2,lz]});
  put('trim',api.box(1.0,h-SL,fw-0.6).translate(lx,y0+(h-SL)/2,zc));
  api.collider({kind:'box',halfExtents:[0.5,(h-SL)/2,(fw-0.6)/2],offset:[lx,y0+(h-SL)/2,zc]});
  put('trim',api.box(lw,0.9,0.3).translate(lx,y0+h+0.45,zr)); api.collider({kind:'box',halfExtents:[lw/2,0.5,0.15],offset:[lx,y0+h+0.5,zr]});
  put('trim',api.box(0.3,0.9,fw+0.35).translate(d*(hw-0.15),y0+h+0.45,lz)); api.collider({kind:'box',halfExtents:[0.15,0.5,(fw+0.35)/2],offset:[d*(hw-0.15),y0+h+0.5,lz]});
}
api.add(acc.wall,wallM); api.add(acc.trim,trimM); api.add(acc.niche,nicheM); api.add(acc.step,marble); api.add(acc.pave,paveM);
return api.build();

marble-flight.source:
const W = params.width, H = params.height, run = params.run;
const n = Math.max(4, Math.round(params.steps));
const R = run / 2, h = H / n, t = run / n;
const wallT = 0.9, para = 1.1, pyl = 1.5;
const hAt = (z) => H * (R - z) / run;
const marble = { preset: 'stone', finish: 'marble', color: params.color, roughness: 0.42, surface: { layers: [ { kind: 'veins', amount: 0.25, scale: 1.2 }, { kind: 'grime', amount: 0.3 }, { kind: 'edgeWear', amount: 0.6 } ] } };
const wallMat = { preset: 'stone', finish: 'marble', color: params.wallColor, roughness: 0.5, surface: { layers: [ { kind: 'veins', amount: 0.15 }, { kind: 'grime', amount: 0.4 }, { kind: 'streaks', amount: 0.25 }, { kind: 'edgeWear', amount: 0.6 } ] } };
const trim = { preset: 'stone', finish: 'marble', color: params.trimColor, roughness: 0.38, surface: { layers: [ { kind: 'grime', amount: 0.25 }, { kind: 'edgeWear', amount: 0.5 } ] } };
const bronze = { preset: 'metal', finish: 'brass', color: '#8a5a2e', metalness: 0.85, roughness: 0.4 };
const coal = { preset: 'emissive', color: '#ff7a1a', emissive: '#ff6a10', emissiveIntensity: 3 };
let stepsM = null, trimM = null, wallM = null, bronzeM = null, coalM = null;
const add = (cur, m) => { if (cur) { cur.merge(m); return cur; } return m; };
for (let i = 0; i < n; i++) {
  const top = (i + 1) * h;
  const zc = R - (i + 0.5) * t;
  stepsM = add(stepsM, api.box(W, top, t).translate(0, top / 2, zc));
  trimM = add(trimM, api.box(W, 0.035, 0.07).translate(0, top - 0.0175, zc + t / 2 - 0.02));
  api.collider({ kind: 'box', halfExtents: [W / 2, top / 2, t / 2], offset: [0, top / 2, zc] });
}
for (const s of [-1, 1]) {
  const xw = s * (W / 2 + wallT / 2);
  wallM = add(wallM, api.box(wallT, 1, run).translate(xw, 0.5, 0).warp((x, y, z) => [x, y * (para + hAt(z)), z]));
  trimM = add(trimM, api.box(wallT + 0.24, 0.22, run).warp((x, y, z) => [x + xw, y + 0.11 + para + hAt(z), z]));
  wallM = add(wallM, api.box(wallT + 0.16, 0.6, run).translate(xw, 0.3, 0));
  for (let zz = R - 3; zz > -R + 2; zz -= 3.5) {
    const yOut = Math.max(1.2, 0.5 * (para + hAt(zz)) + 0.3);
    trimM = add(trimM, api.torus(0.34, 0.055).rotate(0, 90, 0).translate(s * (W / 2 + wallT + 0.04), yOut, zz));
    trimM = add(trimM, api.torus(0.26, 0.045).rotate(0, 90, 0).translate(s * (W / 2 - 0.03), hAt(zz) + 0.62, zz));
  }
  const pts = [];
  for (const dx of [-wallT / 2, wallT / 2]) for (const zz of [-R, R]) { pts.push(xw + dx, 0, zz); pts.push(xw + dx, para + hAt(zz), zz); }
  api.collider({ kind: 'hull', points: pts, offset: [0, 0, 0] });
  for (const pz of [[R - pyl / 2, para + 1.5], [-R + pyl / 2, H + para + 1.5]]) {
    const zp = pz[0], hp = pz[1];
    wallM = add(wallM, api.box(pyl, hp, pyl).translate(xw, hp / 2, zp));
    trimM = add(trimM, api.box(pyl + 0.25, 0.45, pyl + 0.25).translate(xw, 0.225, zp));
    trimM = add(trimM, api.box(pyl + 0.18, 0.14, pyl + 0.18).translate(xw, hp - 0.32, zp));
    trimM = add(trimM, api.box(pyl + 0.32, 0.25, pyl + 0.32).translate(xw, hp + 0.125, zp));
    trimM = add(trimM, api.torus(0.36, 0.06).translate(xw, hp - 1.15, zp + pyl / 2 + 0.05));
    api.collider({ kind: 'box', halfExtents: [pyl / 2, hp / 2, pyl / 2], offset: [xw, hp / 2, zp] });
    if (params.bowls) {
      const yb = hp + 0.25;
      bronzeM = add(bronzeM, api.lathe([[0, 0], [0.2, 0], [0.2, 0.08], [0.09, 0.16], [0.09, 0.3], [0.2, 0.36], [0.46, 0.56], [0.52, 0.66], [0.47, 0.66], [0.2, 0.46], [0, 0.44]], 20).translate(xw, yb, zp));
      coalM = add(coalM, api.cylinder(0.44, 0.38, 0.06, 16).translate(xw, yb + 0.6, zp));
    }
  }
}
api.add(stepsM, marble);
api.add(wallM, wallMat);
api.add(trimM, trim);
if (bronzeM) api.add(bronzeM, bronze);
if (coalM) api.add(coalM, coal);
return api.build();

marble-grand-stair.source:
const W = params.width, band = params.band, H = params.height;
const N = 6, h = H / N, topD = 6, D = N * band + topD;
const half = W / 2, land = 3, x0 = half - land, run = 2 * x0;
const n = Math.max(8, Math.round(h / 0.17));
const r = h / n, t = run / n, pT = 0.45, ph = 1.0;
const ang = Math.atan2(h, run) * 180 / Math.PI;
const len = Math.sqrt(run * run + h * h);
const S = [], WL = [], T = [];
function bx(arr, xa, xb, ya, yb, za, zb) { arr.push(api.box(xb - xa, yb - ya, zb - za).translate((xa + xb) / 2, (ya + yb) / 2, (za + zb) / 2)); }
function rb(arr, xa, xb, ya, yb, za, zb) { arr.push(api.roundedBox(xb - xa, yb - ya, zb - za, 0.04, 2).translate((xa + xb) / 2, (ya + yb) / 2, (za + zb) / 2)); }
function col(xa, xb, ya, yb, za, zb) { api.collider({ kind: 'box', halfExtents: [(xb - xa) / 2, (yb - ya) / 2, (zb - za) / 2], offset: [(xa + xb) / 2, (ya + yb) / 2, (za + zb) / 2] }); }
for (let k = 1; k <= N; k++) {
  const zf = D - band * k;
  bx(WL, -half, half, (k - 1) * h, k * h, 0, zf);
  col(-half, half, (k - 1) * h, k * h, 0, zf);
  rb(T, -half, half, k * h - 0.38, k * h + 0.02, zf - 0.02, zf + 0.16);
  bx(T, -half, half, (k - 1) * h + h * 0.5 - 0.12, (k - 1) * h + h * 0.5 + 0.12, zf - 0.02, zf + 0.09);
}
for (let k = 0; k < N; k++) {
  const dir = k % 2 === 0 ? 1 : -1;
  const za = D - band * (k + 1), zb = D - band * k, zt = zb - pT;
  const y0 = k * h, y1 = (k + 1) * h;
  for (let i = 0; i < n; i++) {
    let xa, xb;
    if (dir > 0) { xa = -x0 + i * t; xb = xa + t; } else { xb = x0 - i * t; xa = xb - t; }
    bx(S, xa, xb, y0, y0 + (i + 1) * r, za, zt);
  }
  const la = dir > 0 ? x0 : -half, lb = dir > 0 ? half : -x0;
  bx(WL, la, lb, y0, y1 - 0.16, za, zb);
  bx(S, la, lb, y1 - 0.16, y1, za, zb);
  col(la, lb, y0, y1, za, zb);
  const th = ang * dir * Math.PI / 180;
  api.collider({ kind: 'box', halfExtents: [len / 2, 0.3, (zt - za) / 2], offset: [Math.sin(th) * 0.3, y0 + h / 2 - Math.cos(th) * 0.3 + r / 2, (za + zt) / 2], rotation: [0, 0, ang * dir] });
