const W = params.width, D = params.depth, s = params.slab;
const nx = Math.max(1, Math.round(W / s)), nz = Math.max(1, Math.round(D / s));
const sx = W / nx, sz = D / nz;
const mats = [
  { finish: 'marble', color: params.color, roughness: 0.55 },
  { finish: 'marble', color: api.mix(params.color, '#d6c9b2', 0.45), roughness: 0.6 },
  { finish: 'marble', color: api.mix(params.color, '#ffffff', 0.35), roughness: 0.5 }
];
const groups = [null, null, null];
for (let i = 0; i < nx; i++) {
  for (let j = 0; j < nz; j++) {
    const x = -W / 2 + sx * (i + 0.5);
    const z = -D / 2 + sz * (j + 0.5);
    const h = 0.06 + api.rng() * 0.02;
    const b = api.roundedBox(sx - 0.035, h, sz - 0.035, 0.015, 1)
      .rotate((api.rng() - 0.5) * 0.5, 0, (api.rng() - 0.5) * 0.5)
      .translate(x, 0.03 + h / 2, z);
    const k = Math.floor(api.rng() * 3) % 3;
    if (groups[k]) groups[k].merge(b); else groups[k] = b;
  }
}
for (let k = 0; k < 3; k++) if (groups[k]) api.add(groups[k], mats[k]);
api.add(api.box(W, 0.04, D).translate(0, 0.02, 0), { finish: 'concrete', color: '#8c8272', roughness: 0.95 });
api.collider({ kind: 'box', halfExtents: [W / 2, 0.05, D / 2], offset: [0, 0.05, 0] });
return api.build();

