const W = params.width, H = params.height, TI = Math.max(2, Math.round(params.tiers)), B = params.band, D = params.depth;
const half = W / 2, fx = half - params.landing;
const rise = H / TI;
const T = [];
for (let i = 0; i < TI; i++) T.push((i + 1) * rise);
const N = Math.max(4, Math.round(params.steps));
const tw = params.tongueWidth, tl = params.tongue;
const M = {
  wall: { color: params.wallColor, roughness: 0.78, surface: { layers: [ { kind: 'tone', amount: 0.2, scale: 3 }, { kind: 'streaks', amount: 0.22 }, { kind: 'grime', amount: 0.25, mask: { down: 0.2 } }, { kind: 'edgeWear', amount: 0.5 } ] } },
  step: { color: params.color, roughness: 0.6, surface: { layers: [ { kind: 'tone', amount: 0.12, scale: 2 }, { kind: 'grime', amount: 0.12 }, { kind: 'edgeWear', amount: 0.6 } ] } },
  trim: { color: params.trimColor, roughness: 0.5, surface: { layers: [ { kind: 'edgeWear', amount: 0.5 }, { kind: 'grime', amount: 0.12 } ] } },
  plinth: { color: params.plinthColor, roughness: 0.85, surface: { layers: [ { kind: 'grime', amount: 0.4 }, { kind: 'moss', amount: 0.25, mask: { noise: 0.5 } } ] } },
  niche: { color: params.nicheColor, roughness: 0.9 }
};
const acc = {};
function put(k, m) { if (acc[k]) acc[k].merge(m); else acc[k] = m; }
function bx(k, x0, x1, y0, y1, z0, z1) {
  const w = Math.abs(x1 - x0), h = Math.abs(y1 - y0), d = Math.abs(z1 - z0);
  if (w < 0.001 || h < 0.001 || d < 0.001) return;
  put(k, api.box(w, h, d).translate((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2));
}
function cb(x0, x1, y0, y1, z0, z1) {
  api.collider({ kind: 'box', halfExtents: [Math.abs(x1 - x0) / 2, Math.abs(y1 - y0) / 2, Math.abs(z1 - z0) / 2], offset: [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2] });
}
function solid(k, x0, x1, y0, y1, z0, z1) { bx(k, x0, x1, y0, y1, z0, z1); cb(x0, x1, y0, y1, z0, z1); }
const bal = api.lathe([[0.065, 0], [0.065, 0.07], [0.045, 0.12], [0.035, 0.24], [0.07, 0.42], [0.04, 0.6], [0.032, 0.64], [0.055, 0.67], [0.055, 0.72], [0, 0.72]], 8);
function railX(xa, ya, xb, yb, z) {
  if (xb < xa) { const tx = xa; xa = xb; xb = tx; const ty = ya; ya = yb; yb = ty; }
  const dx = xb - xa, dy = yb - ya;
  if (dx < 0.2) return;
  const len = Math.sqrt(dx * dx + dy * dy);
  const ang = Math.atan2(dy, dx) * 180 / Math.PI;
  const mx = (xa + xb) / 2, my = (ya + yb) / 2;
  put('plinth', api.box(len, 0.16, 0.34).translate(0, 0.08, 0).rotate(0, 0, ang).translate(mx, my, z));
  put('trim', api.box(len, 0.12, 0.3).translate(0, 0.94, 0).rotate(0, 0, ang).translate(mx, my, z));
  const n = Math.max(2, Math.floor(dx / 0.3));
  for (let i = 0; i < n; i++) { const f = (i + 0.5) / n; put('trim', bal.clone().translate(xa + dx * f, ya + dy * f + 0.16, z)); }
  put('trim', api.box(0.36, 1.12, 0.36).translate(xa, ya + 0.56, z));
  put('trim', api.box(0.36, 1.12, 0.36).translate(xb, yb + 0.56, z));
  const r = ang * Math.PI / 180;
  api.collider({ kind: 'box', halfExtents: [len / 2, 0.55, 0.16], offset: [mx - 0.55 * Math.sin(r), my + 0.55 * Math.cos(r), z], rotation: [0, 0, ang] });
}
function railZ(x, za, zb, y) {
  const z0 = Math.min(za, zb), z1 = Math.max(za, zb), len = z1 - z0;
  if (len < 0.2) return;
  bx('plinth', x - 0.17, x + 0.17, y, y + 0.16, z0, z1);
  bx('trim', x - 0.15, x + 0.15, y + 0.88, y + 1.0, z0, z1);
  const n = Math.max(2, Math.floor(len / 0.3));
  for (let i = 0; i < n; i++) put('trim', bal.clone().translate(x, y + 0.16, z0 + len * (i + 0.5) / n));
  bx('trim', x - 0.18, x + 0.18, y, y + 1.12, z0, z0 + 0.36);
  bx('trim', x - 0.18, x + 0.18, y, y + 1.12, z1 - 0.36, z1);
