function archShape(w, h) {
  const pts = [[-w / 2, 0], [w / 2, 0], [w / 2, h - w / 2]];
  for (let i = 1; i < 12; i++) { const a = Math.PI * i / 12; pts.push([w / 2 * Math.cos(a), h - w / 2 + w / 2 * Math.sin(a)]); }
  pts.push([-w / 2, h - w / 2]);
  return pts;
}
function faceDecor(z, y0, y1, niches) {
  const pw = 0.6, n = Math.max(2, Math.round(W / 3.25));
  const xs = [];
  for (let i = 0; i <= n; i++) xs.push(-half + 0.4 + (W - 0.8) * i / n);
  for (let i = 0; i < xs.length; i++) {
    const x = xs[i];
    bx('trim', x - pw / 2, x + pw / 2, y0 + 0.6, y1 - 0.45, z, z + 0.16);
    bx('trim', x - pw / 2 - 0.08, x + pw / 2 + 0.08, y1 - 0.75, y1 - 0.45, z, z + 0.22);
    bx('trim', x - pw / 2 - 0.08, x + pw / 2 + 0.08, y0 + 0.6, y0 + 0.85, z, z + 0.22);
  }
  bx('plinth', -half - 0.05, half + 0.05, y0, y0 + 0.6, z, z + 0.2);
  bx('trim', -half - 0.15, half + 0.15, y1 - 0.45, y1 - 0.12, z, z + 0.3);
  bx('trim', -half - 0.05, half + 0.05, y1 - 0.12, y1, z, z + 0.15);
  bx('trim', -half - 0.05, half + 0.05, y0 + (y1 - y0) * 0.72, y0 + (y1 - y0) * 0.72 + 0.18, z, z + 0.18);
