      const cx = (xs[i] + xs[i + 1]) / 2;
      if (Math.abs(cx) < tw / 2 + 0.6) continue;
      put('trim', api.extrude(archShape(1.7, nh + 0.3), 0.05).translate(cx, y0 + 1.25, z + 0.03));
