    }
  }
}
const T0 = T[0];
solid('wall', -half, half, 0, T0, -D, 0);
solid('wall', -tw / 2, tw / 2, 0, T0, 0, tl);
bx('step', -half, half, T0, T0 + 0.05, -B, tl);
faceDecor(0, 0, T0, true);
for (let k = 1; k < TI; k++) {
  solid('wall', -half, half, T[k - 1], T[k], -D, -B * (k + 1));
  faceDecor(-B * (k + 1), T[k - 1], T[k], false);
}
bx('step', -half, half, T[TI - 1], T[TI - 1] + 0.05, -D, -B * TI);
railX(-half + 0.2, T0, -tw / 2, T0, -0.2);
railX(tw / 2, T0, half - 0.2, T0, -0.2);
railZ(half - 0.18, 0, -B, T0);
railZ(-half + 0.18, 0, -B, T0);
for (let k = 1; k < TI; k++) {
  const L = T[k - 1], Hh = T[k], zf = -B * k, zb = -B * (k + 1), odd = k % 2 === 1;
  if (odd) solid('wall', -half, -fx, L, Hh, zb, zf); else solid('wall', fx, half, L, Hh, zb, zf);
  bx('step', odd ? -half : fx, odd ? -fx : half, Hh, Hh + 0.05, zb, zf);
  bx('step', odd ? fx : -half, odd ? half : -fx, L, L + 0.05, zb, zf);
  const r = (Hh - L) / N, tr = 2 * fx / N;
  for (let j = 0; j < N; j++) {
    const a = odd ? fx - (j + 1) * tr : -fx + j * tr;
    bx(j % 2 ? 'trim' : 'step', a, a + tr, L, L + (j + 1) * r, zb, zf);
  }
  const run = 2 * fx, ang = Math.atan2(Hh - L, run), deg = ang * 180 / Math.PI;
