  const zr = zf - 0.2;
  if (odd) { railX(-fx, Hh + r / 2, fx, L + r / 2, zr); railX(-half + 0.2, Hh, -fx, Hh, zr); }
  else { railX(-fx, L + r / 2, fx, Hh + r / 2, zr); railX(fx, Hh, half - 0.2, Hh, zr); }
  railZ(half - 0.18, zf, zb, odd ? L : Hh);
  railZ(-half + 0.18, zf, zb, odd ? Hh : L);
}
const TT = T[TI - 1], zt = -B * TI - 0.2;
if ((TI - 1) % 2 === 1) railX(-fx, TT, half - 0.2, TT, zt); else railX(-half + 0.2, TT, fx, TT, zt);
railZ(half - 0.18, -B * TI, -D, TT);
railZ(-half + 0.18, -B * TI, -D, TT);
for (const k in acc) api.add(acc[k], M[k]);
