const W=params.width,Ht=params.height,B=params.band,N=Math.max(2,Math.round(params.tiers));const D=Math.max(params.depth,N*B+2);const half=W/2,rl=half-3;const H=Ht/N,run=2*rl;const ns=Math.max(4,Math.round(H/0.3));const r=H/ns,tr=run/ns;
const marble={finish:'marble',color:params.wallColor,roughness:0.5,surface:{layers:[{kind:'veins',amount:0.15,scale:1.2},{kind:'grime',amount:0.3},{kind:'streaks',amount:0.3,scale:2},{kind:'edgeWear',amount:0.5}]}};
const trim={finish:'marble',color:params.trimColor,roughness:0.4,surface:{layers:[{kind:'grime',amount:0.25},{kind:'edgeWear',amount:0.6}]}};
function dirOf(k){return (k%2===0)?1:-1;}
function surf(k,x){const d=dirOf(k);const s=x*d+rl;if(s<0)return k*H;if(s>=run)return (k+1)*H;const i=Math.min(ns-1,Math.floor(s/tr));return k*H+(i+1)*r;}
function seg(x0,y0,x1,y1,h,t,z,mat,col){const dx=x1-x0,dy=y1-y0,len=Math.sqrt(dx*dx+dy*dy),ang=Math.atan2(dy,dx)*180/Math.PI;api.add(api.box(len,h,t).rotate(0,0,ang).translate((x0+x1)/2,(y0+y1)/2,z),mat);if(col){api.collider({kind:'box',halfExtents:[len/2,0.55,0.16],offset:[(x0+x1)/2,(y0+y1)/2-0.45,z],rotation:[0,0,ang]});}}
const proto=api.lathe([[0,0],[0.075,0],[0.075,0.08],[0.05,0.13],[0.08,0.36],[0.045,0.6],[0.065,0.66],[0.065,0.7],[0,0.7]],8);
let bal=null;function baluster(x,base,top,z){const h=top-base;if(h<0.3)return;const m=proto.clone().scale(1,h/0.7,1).translate(x,base,z);if(bal)bal.merge(m);else bal=m;}
function hullXY(xy,z0,z1){const p=[];for(const q of xy){p.push(q[0],q[1],z0);p.push(q[0],q[1],z1);}return p;}
for(let k=0;k<N;k++){const d=dirOf(k);const yL=k*H,yH=(k+1)*H;const zf=-k*B,zc=zf-B/2;let pts=[];if(k===0)pts.push([-rl,0]);else pts.push([-half,0]);pts.push([half,0]);pts.push([half,yH]);pts.push([rl,yH]);for(let i=ns-1;i>=0;i--){const xi=-rl+i*tr;pts.push([xi,yL+(i+1)*r]);if(!(k===0&&i===0))pts.push([xi,yL+i*r]);}if(k>0)pts.push([-half,yL]);if(d<0)pts=pts.map(p=>[-p[0],p[1]]).reverse();api.add(api.extrude(pts,B).translate(0,0,zc),marble);
const ramp=[[-rl,0],[-rl,yL+0.15],[rl,yH+0.15],[rl,0]].map(p=>[p[0]*d,p[1]]);api.collider({kind:'hull',points:hullXY(ramp,zf-B,zf),offset:[0,0,0]});api.collider({kind:'box',halfExtents:[1.5,yH/2,B/2],offset:[d*(rl+1.5),yH/2,zc]});if(k>0)api.collider({kind:'box',halfExtents:[1.5,yL/2,B/2],offset:[-d*(rl+1.5),yL/2,zc]});
const zr=zf-0.22;const y0r=yL+r+0.9,y1r=yH+0.9;seg(-d*rl,y0r,d*rl,y1r,0.14,0.32,zr,trim,true);seg(d*rl,y1r,d*half,y1r,0.14,0.32,zr,trim,true);
for(let s=0.2;s<run+3-0.1;s+=0.42){const x=d*(-rl+s);const base=s<run?surf(k,x):yH;const top=s<run?(yL+r+0.9+s*(H-r)/run):yH+0.9;baluster(x,base,top-0.07,zr);}
seg(-d*rl,yL-0.3,d*rl,yH-0.3,0.24,0.3,zf,trim,false);seg(d*rl,yH-0.3,d*half,yH-0.3,0.24,0.3,zf,trim,false);
for(let x=-half+2;x<=half-2+0.01;x+=4){const top=surf(k,x)-0.55;const bot=k===0?0:surf(k-1,x);const h=top-bot;if(h>1.2){api.add(api.box(0.6,h,0.2).translate(x,bot+h/2,zf+0.08),trim);api.add(api.box(0.8,0.22,0.3).translate(x,top-0.11,zf+0.1),trim);}}}
