marble-switchback-stair.source:
const W = 3, run = 10, nF = 8, nS = 24;
const yb0 = 0.5, yTop = params.top;
const r = (yTop - yb0) / nF;
const zA0 = -23.5, zA1 = -20.5, zB1 = -17.5;
const M = { preset: 'stone', finish: 'marble', color: params.color, roughness: 0.4 };
const S = { preset: 'stone', finish: 'stone', color: params.pierColor, roughness: 0.85 };
function addM(m) { api.add(m, M); }
function addS(m) { api.add(m, S); }
const bal = api.lathe([[0,0],[0.075,0],[0.075,0.07],[0.045,0.14],[0.08,0.36],[0.05,0.6],[0.07,0.7],[0.07,0.78],[0,0.78]], 6);
function blk(x0, x1, y0, y1, z0, z1, acc, c) {
  acc(api.box(x1 - x0, y1 - y0, z1 - z0).translate((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2));
  if (c) api.collider({ kind: 'box', halfExtents: [(x1 - x0) / 2, (y1 - y0) / 2, (z1 - z0) / 2], offset: [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2] });
}
function balLine(xa, za, xb, zb, y) {
  const len = Math.abs(xb - xa) + Math.abs(zb - za);
  const alongX = Math.abs(xb - xa) > Math.abs(zb - za);
  const n = Math.max(2, Math.round(len / 0.4));
  for (let i = 0; i <= n; i++) { const t = i / n; addM(bal.clone().translate(xa + (xb - xa) * t, y + 0.12, za + (zb - za) * t)); }
  const cx = (xa + xb) / 2, cz = (za + zb) / 2;
