var acc = { s: null, m: null };
function put(k, mesh) { if (acc[k]) { acc[k].merge(mesh); } else { acc[k] = mesh; } }
function bx(x0, x1, y0, y1, z0, z1) {
  var ax = Math.min(x0, x1), bb = Math.max(x0, x1);
  return api.box(bb - ax, y1 - y0, z1 - z0).translate((ax + bb) / 2, (y0 + y1) / 2, (z0 + z1) / 2);
}
function col(x0, x1, y0, y1, z0, z1) {
  var ax = Math.min(x0, x1), bb = Math.max(x0, x1);
