    var xa = -s * (half - land) + s * i * tread, xb = xa + s * tread;
    var top = base + (i + 1) * rise;
    put('m', bx(xa, xb, base, top, z0, zr));
    put('m', bx(xa, xb, base, top + ph, zr, z1));
  }
  var ea = s * (half - land), eb = s * half;
  put('m', bx(ea, eb, base, base + R, z0, z1));
  col(ea, eb, base, base + R, z0, z1);
  put('m', bx(ea, eb, base + R, base + R + ph, zr, z1));
  col(ea, eb, base + R, base + R + ph, zr, z1);
  put('m', bx(eb - s * pt, eb, base + R, base + R + ph, z0, zr));
  col(eb - s * pt, eb, base + R, base + R + ph, z0, zr);
  var sa = -s * half;
  put('m', bx(sa, sa + s * pt, base, base + ph, z0, z1));
