  var a = s * th, ar = a * Math.PI / 180;
  api.collider({ kind: 'box', halfExtents: [L / 2 + 0.3, 0.3, (z1 - z0) / 2], offset: [0.3 * Math.sin(ar), base + R / 2 - 0.3 * Math.cos(ar), (z0 + z1) / 2], rotation: [0, 0, a] });
