}
api.add(acc.s, { preset: 'stone', finish: 'stone', color: params.wallColor, roughness: 0.85, surface: { layers: [{ kind: 'streaks', amount: 0.5 }, { kind: 'grime', amount: 0.4 }, { kind: 'edgeWear', amount: 0.4 }] } });
