  fa('trim', trimMat, f, api.box(0.14, oh + 0.1, 0.1).translate(x - ow / 2 - 0.07, y + oh / 2, 0.02));
  fa('trim', trimMat, f, api.box(0.14, oh + 0.1, 0.1).translate(x + ow / 2 + 0.07, y + oh / 2, 0.02));
  fa('trim', trimMat, f, api.box(ow + 0.5, 0.2, 0.14).translate(x, y + oh + 0.1, 0.04));
