    fa('trim', trimMat, f, api.box(ow + 0.32, 0.08, 0.22).translate(x, y - 0.04, 0.08));
    fa('frame', frameMat, f, api.box(0.045, oh, 0.03).translate(x, y + oh / 2, 0.035));
    fa('frame', frameMat, f, api.box(ow, 0.045, 0.03).translate(x, y + oh * 0.62, 0.035));
