  for (const s of [-1, 1]) fa('trim', trimMat, f, api.box(0.16, 0.3, 0.6).translate(x + s * (bw / 2 - 0.2), y - 0.29, 0.3));
  fa('iron', ironMat, f, api.box(bw, 0.05, 0.05).translate(x, y + 1.0, 0.9));
