    fa('iron', ironMat, f, api.box(0.04, 0.05, 0.9).translate(x + s * (bw / 2 - 0.02), y + 1.0, 0.45));
    for (let k = 1; k < 6; k++) fa('iron', ironMat, f, api.box(0.022, 0.9, 0.022).translate(x + s * (bw / 2 - 0.02), y + 0.55, 0.9 * k / 6));
