put('trim', trimMat, api.box(w + 0.16, gy, d + 0.16).translate(0, gy / 2, 0));
put('wall', wallMat, api.roundedBox(w, H + 0.1, d, 0.06, 2).translate(0, gy - 0.1 + (H + 0.1) / 2, 0));
for (let f = 1; f < floors; f++) put('trim', trimMat, api.box(w + 0.12, 0.14, d + 0.12).translate(0, gy + f * fh, 0));
