  for (let i = 0; i < nf; i++) opening(1, -w / 2 + sp * (i + 0.5), fy + 0.95, 0.75, 1.2, 'win', false);
}
const ov = 0.5;
const W = w + 2 * ov, D = d + 2 * ov;
const ry = top + 0.06;
let roofTop = ry;
if (params.roof === 'flat') {
  put('wall', wallMat, api.box(w, 0.7, 0.2).translate(0, ry + 0.35, d / 2 - 0.1));
  put('wall', wallMat, api.box(w, 0.7, 0.2).translate(0, ry + 0.35, -d / 2 + 0.1));
  put('wall', wallMat, api.box(0.2, 0.7, d).translate(w / 2 - 0.1, ry + 0.35, 0));
  put('wall', wallMat, api.box(0.2, 0.7, d).translate(-w / 2 + 0.1, ry + 0.35, 0));
  put('trim', trimMat, api.box(w + 0.08, 0.08, 0.3).translate(0, ry + 0.74, d / 2 - 0.1));
  put('trim', trimMat, api.box(w + 0.08, 0.08, 0.3).translate(0, ry + 0.74, -d / 2 + 0.1));
  put('trim', trimMat, api.box(0.3, 0.08, d).translate(w / 2 - 0.1, ry + 0.74, 0));
  put('trim', trimMat, api.box(0.3, 0.08, d).translate(-w / 2 + 0.1, ry + 0.74, 0));
  const hx = w / 2 - 1.3, hz = -d / 2 + 1.3;
  put('wall', wallMat, api.roundedBox(2.0, 2.3, 2.0, 0.05, 2).translate(hx, ry + 1.15, hz));
  put('trim', trimMat, api.box(2.3, 0.12, 2.3).translate(hx, ry + 2.36, hz));
  put('door', doorMat, api.box(0.8, 1.9, 0.06).translate(hx, ry + 0.95, hz + 1.01));
  const px0 = -w / 2 + 0.5, px1 = Math.min(px0 + 2.8, w / 2 - 0.5), pz0 = d / 2 - 0.5, pz1 = Math.max(pz0 - 2.4, -d / 2 + 0.5);
  for (const px of [px0, px1]) for (const pz of [pz0, pz1]) put('door', doorMat, api.box(0.1, 2.3, 0.1).translate(px, ry + 1.15, pz));
  for (let k = 0; k < 6; k++) put('door', doorMat, api.box(px1 - px0 + 0.3, 0.07, 0.07).translate((px0 + px1) / 2, ry + 2.33, pz0 + (pz1 - pz0) * k / 5));
